1: /**
2:  * Camada de abstração entre a UI e o estado global (Zustand).
3:  * Nenhum componente de UI deve importar o Zustand diretamente.
4:  * Este hook é o único ponto de acesso ao estado de reservas.
5:  */
6: 
7: "use client";
8: 
9: import { useCallback, useMemo } from "react";
10: import { useReservasStore, type Reserva, type StatusReserva } from "@/store/useReservasStore";
11: import {
12:   calcularValorSinal,
13:   calcularValorPendente,
14:   calcularValorTotal,
15: } from "@/lib/constants";
16: import type { Esporte } from "@/lib/quadras";
17: 
18: // ─── Tipos de entrada para criação ───────────────────────────────────────────
19: 
20: export interface DadosCriacaoReserva {
21:   quadraId: string;
22:   data: string;
23:   horarios: string[];
24:   nomeCliente?: string;
25:   whatsappCliente?: string;
26:   cpfCliente?: string;
27:   esporte?: Esporte;
28:   observacoes?: string;
29: }
30: 
31: // ─── Hook ─────────────────────────────────────────────────────────────────────
32: 
33: export function useReservasService() {
34:   const { reservas, adicionarReserva, atualizarReserva, removerReserva, getReservaById } =
35:     useReservasStore();
36: 
37:   // ── Queries ────────────────────────────────────────────────────────────────
38: 
39:   /** Reservas ativas para uma data e quadra específicas (exclui canceladas) */
40:   const getHorariosOcupados = useCallback(
41:     (data: string, quadraId: string): string[] => {
42:       return reservas
43:         .filter(
44:           (r) =>
45:             r.data === data &&
46:             r.quadraId === quadraId &&
47:             r.status !== "cancelada"
48:         )
49:         .flatMap((r) => r.horarios);
50:     },
51:     [reservas]
52:   );
53: 
54:   /** Verifica se um horário específico está ocupado numa quadra/data */
55:   const isHorarioOcupado = useCallback(
56:     (data: string, quadraId: string, horario: string): boolean => {
57:       return getHorariosOcupados(data, quadraId).includes(horario);
58:     },
59:     [getHorariosOcupados]
60:   );
61: 
62:   /** Retorna todos os horários ocupados em qualquer quadra para um dia */
63:   const getHorariosOcupadosDia = useCallback(
64:     (data: string): { quadraId: string; horario: string }[] => {
65:       return reservas
66:         .filter((r) => r.data === data && r.status !== "cancelada")
67:         .flatMap((r) => r.horarios.map((h) => ({ quadraId: r.quadraId, horario: h })));
68:     },
69:     [reservas]
70:   );
71: 
72:   /** Reservas para o Dashboard Admin */
73:   const getTodasReservas = useCallback((): Reserva[] => reservas, [reservas]);
74: 
75:   /** Totais financeiros */
76:   const financeiro = useMemo(() => {
77:     const confirmadas = reservas.filter((r) => r.status === "confirmada");
78:     const naoCaneladas = reservas.filter((r) => r.status !== "cancelada");
79:     return {
80:       totalConfirmado: confirmadas.reduce((acc, r) => acc + r.valorSinal, 0),
81:       totalPrevisto: naoCaneladas.reduce((acc, r) => acc + r.valorTotal, 0),
82:       pendenteSinalConfirmado: confirmadas.reduce(
83:         (acc, r) => acc + r.valorPendente,
84:         0
85:       ),
86:     };
87:   }, [reservas]);
88: 
89:   // ── Mutations ──────────────────────────────────────────────────────────────
90: 
91:   /**
92:    * Cria uma reserva com status "em_processamento" (lock temporário).
93:    * Retorna o ID gerado para controle do fluxo de checkout.
94:    */
95:   const criarReservaEmProcessamento = useCallback(
96:     (dados: DadosCriacaoReserva): string => {
97:       const horarios = [...dados.horarios].sort();
98:       const valorTotal = calcularValorTotal(horarios);
99:       const id = `rsv_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
100: 
101:       const reserva: Reserva = {
102:         id,
103:         quadraId: dados.quadraId,
104:         data: dados.data,
105:         horarios,
106:         horaInicio: horarios[0],
107:         horaFim: `${String(parseInt(horarios[horarios.length - 1]) + 1).padStart(2, "0")}:00`,
108:         nomeCliente: dados.nomeCliente ?? "",
109:         whatsappCliente: dados.whatsappCliente ?? "",
110:         cpfCliente: dados.cpfCliente ?? "",
111:         valorTotal,
112:         valorSinal: calcularValorSinal(valorTotal),
113:         valorPendente: calcularValorPendente(valorTotal),
114:         status: "em_processamento",
115:         statusWhatsApp: "nao_enviado",
116:         criadaEm: new Date().toISOString(),
117:         esporte: dados.esporte,
118:         observacoes: dados.observacoes,
119:       };
120: 
121:       adicionarReserva(reserva);
122:       return id;
123:     },
124:     [adicionarReserva]
125:   );
126: 
127:   /**
128:    * Atualiza os dados de identificação de uma reserva em processamento
129:    * e mantém o status "em_processamento".
130:    */
131:   const atualizarIdentificacao = useCallback(
132:     (
133:       id: string,
134:       dados: Pick<Reserva, "nomeCliente" | "whatsappCliente" | "cpfCliente"> & {
135:         esporte?: Esporte;
136:         observacoes?: string;
137:       }
138:     ) => {
139:       atualizarReserva(id, dados);
140:     },
141:     [atualizarReserva]
142:   );
143: 
144:   /**
145:    * Confirma o pagamento — atualiza status e recálculo se integral.
146:    */
147:   const confirmarPagamento = useCallback(
148:     (id: string, tipoPagamento: "sinal" | "integral") => {
149:       const reserva = getReservaById(id);
150:       if (!reserva) return;
151: 
152:       const atualizacao: Partial<Reserva> = {
153:         status: "pendente", // Ainda precisa comparecer
154:         statusWhatsApp: "enviado",
155:       };
156: 
157:       if (tipoPagamento === "integral") {
158:         atualizacao.valorSinal = reserva.valorTotal;
159:         atualizacao.valorPendente = 0;
160:       }
161: 
162:       atualizarReserva(id, atualizacao);
163:     },
164:     [atualizarReserva, getReservaById]
165:   );
166: 
167:   /** Cancela e libera o lock de uma reserva em processamento */
168:   const liberarLock = useCallback(
169:     (id: string) => {
170:       removerReserva(id);
171:     },
172:     [removerReserva]
173:   );
174: 
175:   /** Admin: cancela uma reserva confirmada */
176:   const cancelarReserva = useCallback(
177:     (id: string) => {
178:       atualizarReserva(id, { status: "cancelada" });
179:     },
180:     [atualizarReserva]
181:   );
182: 
183:   /** Admin: atualiza qualquer campo de uma reserva */
184:   const atualizarStatus = useCallback(
185:     (id: string, status: StatusReserva) => {
186:       atualizarReserva(id, { status });
187:     },
188:     [atualizarReserva]
189:   );
190: 
191:   return {
192:     // Queries
193:     reservas,
194:     getHorariosOcupados,
195:     isHorarioOcupado,
196:     getHorariosOcupadosDia,
197:     getTodasReservas,
198:     financeiro,
199: 
200:     // Mutations
201:     criarReservaEmProcessamento,
202:     atualizarIdentificacao,
203:     confirmarPagamento,
204:     liberarLock,
205:     cancelarReserva,
206:     atualizarStatus,
207:   };
208: }
